lines = open('deploy.log').read().splitlines()
header = lines[0]
errs = [l for l in lines if l.startswith('ERROR')]
strs = [header] + errs
def max_overlap(a,b):
    m = min(len(a),len(b))
    for k in range(m,0,-1):
        if a[-k:]==b[:k]:
            return k
    return 0
for i,a in enumerate(strs):
    for j,b in enumerate(strs):
        if i!=j:
            print(i,j,max_overlap(a,b))
